'use strict';

/**
* Compute the minimum absolute value of a one-dimensional double-precision floating-point ndarray.
*
* @module @stdlib/stats/base/ndarray/dminabs
*
* @example
* import Float64Vector from '@stdlib/ndarray/vector/float64';
* import dminabs from '@stdlib/stats/base/ndarray/dminabs';
*
* var x = new Float64Vector( [ -1.0, 3.0, -4.0, 2.0 ] );
*
* var v = dminabs( [ x ] );
* // returns 1.0
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dminabs;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dminabs = main;
} else {
	dminabs = tmp;
}


// EXPORTS //

export default dminabs;
