'use strict';

/**
* Compute the Minkowski distance between two double-precision floating-point strided arrays.
*
* @module @stdlib/stats/strided/distances/dminkowski
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dminkowski from '@stdlib/stats/strided/distances/dminkowski';
*
* var x = new Float64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0 ] );
* var y = new Float64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0 ] );
*
* var z = dminkowski( x.length, 3, x, 1, y, 1 );
* // returns ~11.543
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dminkowski from '@stdlib/stats/strided/distances/dminkowski';
*
* var x = new Float64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0 ] );
* var y = new Float64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0 ] );
*
* var z = dminkowski.ndarray( x.length, 3, x, 1, 0, y, 1, 0 );
* // returns ~11.543
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dminkowski;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dminkowski = main;
} else {
	dminkowski = tmp;
}


// EXPORTS //

export default dminkowski;

// exports: { "ndarray": "dminkowski.ndarray" }
